body:
What does this print?

const marks = [10, 20, 30];
console.log(marks.length);

What does this print?

let x = 5;
x += 2;
console.log(x);

What does this print?

let city;
console.log(city);

What does this print?

const nums = [5, 12, 8, 21];
console.log(nums.filter(n => n > 10));

What does this print?

function greet(name = "Guest") {
  return "Hi " + name;
}
console.log(greet());

What does this print?

const user = { name: "Kavya", city: "Salem" };
const { city } = user;
console.log(city);

In what order are the numbers printed?

console.log(1);
setTimeout(() => console.log(2), 0);
console.log(3);

What does this print?

for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 0);
}

What does this print?

function counter() {
  let count = 0;
  return () => ++count;
}
const next = counter();
next();
console.log(next());

In what order is the output printed?

const p = Promise.resolve(5);
p.then(v => v * 2).then(v => console.log(v));
console.log("done");

What does this print?

const a = { n: 1 };
const b = a;
b.n = 2;
console.log(a.n);

What does this print?

async function getValue() {
  return 7;
}
console.log(typeof getValue());
